package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StdDateFormat__format_TriageGen0Test {

    /**
     * Since _format is protected, we create a subclass to expose it for testing.
     */
    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat() {
            super();
        }

        public TestableStdDateFormat(boolean colonInTz) {
            super();
            // Using the public API to set the internal state for _tzSerializedWithColon
            this.withColonInTimeZone(colonInTz);
        }

        @Override
        public void _format(TimeZone tz, Locale loc, Date date, StringBuffer buffer) {
            super._format(tz, loc, date, buffer);
        }
    }

    @Test
    public void testFormatWithZeroOffsetNoColon() {
        TestableStdDateFormat df = new TestableStdDateFormat(false);
        TimeZone utc = TimeZone.getTimeZone("UTC");
        Locale loc = Locale.US;

        // 2023-10-05 14:30:05.123
        Calendar cal = Calendar.getInstance(utc);
        cal.set(2023, Calendar.OCTOBER, 5, 14, 30, 5);
        cal.set(Calendar.MILLISECOND, 123);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df._format(utc, loc, date, buffer);

        // Expected: 2023-10-05T14:30:05.123+0000
        assertEquals("2023-10-05T14:30:05.123+0000", buffer.toString());
    }

    @Test
    public void testFormatWithZeroOffsetWithColon() {
        TestableStdDateFormat df = new TestableStdDateFormat(true);
        TimeZone utc = TimeZone.getTimeZone("UTC");
        Locale loc = Locale.US;

        Calendar cal = Calendar.getInstance(utc);
        cal.set(2023, Calendar.OCTOBER, 5, 14, 30, 5);
        cal.set(Calendar.MILLISECOND, 123);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df._format(utc, loc, date, buffer);

        // Expected: 2023-10-05T14:30:05.123+00:00
        assertEquals("2023-10-05T14:30:05.123+00:00", buffer.toString());
    }

    @Test
    public void testFormatWithPositiveOffsetWithColon() {
        TestableStdDateFormat df = new TestableStdDateFormat(true);
        TimeZone tz = TimeZone.getTimeZone("GMT+05:30"); // India
        Locale loc = Locale.US;

        Calendar cal = Calendar.getInstance(tz);
        cal.set(2023, Calendar.JANUARY, 1, 10, 0, 0);
        cal.set(Calendar.MILLISECOND, 5);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df._format(tz, loc, date, buffer);

        // Expected: 2023-01-01T10:00:00.005+05:30
        assertEquals("2023-01-01T10:00:00.005+05:30", buffer.toString());
    }

    @Test
    public void testFormatWithNegativeOffsetWithoutColon() {
        TestableStdDateFormat df = new TestableStdDateFormat(false);
        TimeZone tz = TimeZone.getTimeZone("GMT-08:00"); // PST
        Locale loc = Locale.US;

        Calendar cal = Calendar.getInstance(tz);
        cal.set(2023, Calendar.DECEMBER, 31, 23, 59, 59);
        cal.set(Calendar.MILLISECOND, 999);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df._format(tz, loc, date, buffer);

        // Expected: 2023-12-31T23:59:59.999-0800
        assertEquals("2023-12-31T23:59:59.999-0800", buffer.toString());
    }

    @Test
    public void testFormatLargeYear() {
        TestableStdDateFormat df = new TestableStdDateFormat(false);
        TimeZone utc = TimeZone.getTimeZone("UTC");
        Locale loc = Locale.US;

        Calendar cal = Calendar.getInstance(utc);
        cal.set(10000, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df._format(utc, loc, date, buffer);

        // Testing the [databind#2167] logic for years beyond 9999
        // pad4 will likely result in 10000
        assertEquals("10000-01-01T00:00:00.000+0000", buffer.toString());
    }

    @Test
    public void testFormatBCEYear() {
        TestableStdDateFormat df = new TestableStdDateFormat(false);
        TimeZone utc = TimeZone.getTimeZone("UTC");
        Locale loc = Locale.US;

        Calendar cal = Calendar.getInstance(utc);
        // Using a year before 1 AD (BCE)
        cal.set(-500, Calendar.JANUARY, 1, 12, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df._format(utc, loc, date, buffer);

        // The behavior of pad4 for negative numbers depends on implementation, 
        // but for the purpose of coverage, we ensure it executes.
        // GregorianCalendar handles negative years.
        String result = buffer.toString();
        // If pad4 handles negative sign, it will appear in the year part
        // We just verify it doesn't crash and contains the date parts
        assertEquals(true, result.contains("-01-01T12:00:00.000+0000"));
    }
}
